<?php require __DIR__.'/bootstrap.php';messenger_run(function($u){$q=MessengerSecurity::text($_GET['q']??'',100);if($q==='')return [];$limit=max(1,min(100,(int)($_GET['limit']??50)));return Database::fetchAll("SELECT m.id,m.conversation_id,m.body,m.created_at,u.name sender_name,c.title conversation_title FROM chat_messages m JOIN chat_conversations c ON c.id=m.conversation_id JOIN chat_participants p ON p.conversation_id=c.id AND p.user_id=? AND p.deleted_at IS NULL AND p.left_at IS NULL LEFT JOIN users u ON u.id=m.sender_id LEFT JOIN chat_message_user_state us ON us.message_id=m.id AND us.user_id=p.user_id WHERE c.deleted_at IS NULL AND c.is_active=1 AND m.deleted_at IS NULL AND us.hidden_at IS NULL AND MATCH(m.body) AGAINST(? IN BOOLEAN MODE) ORDER BY m.id DESC LIMIT {$limit}",[(int)$u['id'],$q.'*']);});
